  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Investing Basics: Risk, Return and Diversification$j$, $j${"readings": [{"title": "Ecclesiastes 11 (King James Version)", "url": "/portal/bible/Ecclesiastes/11"}], "body": "Saving keeps money safe, and investing puts money to work so it can grow. The master in the parable of the talents expected his servants to use what they were given, and Matthew 25:27 shows the master saying the lazy servant should have put the money to the exchangers. Investing is a tool of stewardship, but it carries risk and requires learning. This lesson is education and not personal investment advice.\n\nThe main investments are these. A stock is a share of ownership in a company. Stock prices rise and fall, and some companies pay a share of profit called a dividend. A bond is a loan to a company or government that pays interest and returns the principal at maturity. A mutual fund pools money from many investors to buy a mix of investments. An exchange traded fund, or ETF, is similar and trades like a stock. An index fund tracks a market index, such as the S&P 500, and often has low costs. Real estate and business ownership are also forms of investing.\n\nRisk and return go together. Investments with higher possible returns usually have higher risk of loss. There is no guaranteed high return. Proverbs 28:20 says, A faithful man shall abound with blessings: but he that maketh haste to be rich shall not be innocent. Be cautious of any offer that promises quick riches or high returns with no risk, which is a sign of fraud.\n\nDiversification means spreading money across many investments. Ecclesiastes 11:2 says, Give a portion to seven, and also to eight; for thou knowest not what evil shall be upon the earth. A diversified fund spreads risk better than one stock. Time horizon matters too. Money needed in a few years should not be exposed to large swings, while long term money has more time to recover.\n\nCosts matter. Fees reduce returns each year, so compare expense ratios. Do not invest money you will need soon, and have an emergency fund and manage high interest debt first. Learn from trusted sources, and consider a fee only fiduciary adviser who is legally bound to act in your interest. Avoid investing in things you do not understand.\n\nYour task: (1) Define stock, bond, mutual fund and index fund. (2) Explain the link between risk and return. (3) Explain diversification using Ecclesiastes 11:2.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Ecclesiastes 11:2 says, Give a portion to seven, and also to eight; for thou knowest not what evil shall be upon the earth. That is the heart of diversification. This lesson is education, not personal investment advice.\n\nNow watch this. A stock is a share of ownership in a company. A bond is a loan that pays interest. A mutual fund pools money from many investors. An ETF trades like a stock. An index fund tracks a market index and often costs less.\n\nRisk and return go together. Higher possible returns usually mean higher risk of loss. Proverbs 28:20 says, he that maketh haste to be rich shall not be innocent. Offers of high returns with no risk are a sign of fraud.\n\nDiversify across many investments. Think about your time horizon. Money needed soon should not swing wildly.\n\nWatch costs. Fees reduce returns. Have an emergency fund and handle high interest debt first. Learn from trusted sources. Avoid what you do not understand.\n\nYour task is to define investments, explain risk and return and explain diversification. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Investing Basics: Risk, Return and Diversification$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Planning for Retirement and Providing for Family$j$, $j${"readings": [{"title": "1 Timothy 5 (King James Version)", "url": "/portal/bible/1Timothy/5"}], "body": "Retirement may seem far away, but time is the greatest advantage a young person has. Proverbs 13:22 says, A good man leaveth an inheritance to his children's children: and the wealth of the sinner is laid up for the just. 1 Timothy 5:8 says, But if any provide not for his own, and specially for those of his house, he hath denied the faith, and is worse than an infidel. Planning ahead is part of caring for family.\n\nRetirement income often comes from three sources: Social Security, employer plans and personal savings. Social Security is a federal program funded by payroll taxes that provides benefits to retired workers, those with disabilities and survivors. It was meant to supplement other savings, not replace them, so most people need more.\n\nA 401(k) is an employer sponsored retirement plan. Workers choose to put part of their pay into it, often before income tax, and some employers add a matching contribution. An employer match is part of your pay, so contribute at least enough to receive the full match when you can. A 403(b) is a similar plan for some nonprofits and schools. An individual retirement account, or IRA, is an account you open yourself. In a traditional IRA, contributions may be tax deductible and withdrawals in retirement are taxed. In a Roth IRA, contributions are made with money that has already been taxed, and qualified withdrawals in retirement are generally tax free. Rules, contribution limits and penalties for early withdrawal change over time and have conditions, so check the Internal Revenue Service at IRS.gov or a qualified adviser.\n\nCompound growth rewards early starters. A person who invests a modest amount each month from age twenty has many more years of growth than one who starts at forty. Consistency matters more than perfection.\n\nEstate planning protects family. A will states how property is to be distributed, and beneficiaries on accounts should be kept up to date. Talk with parents and family about important documents, and plan for the care of dependents. Ministers and church workers should learn how their retirement and housing benefits work.\n\nYour task: (1) Name three sources of retirement income. (2) Explain an employer match. (3) Compare a traditional IRA and a Roth IRA in general terms.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, 1 Timothy 5:8 says, But if any provide not for his own, and specially for those of his house, he hath denied the faith. And Proverbs 13:22 says, A good man leaveth an inheritance to his children's children. Planning ahead is part of caring for family.\n\nNow watch this. Retirement income often comes from Social Security, employer plans and personal savings. Social Security is funded by payroll taxes. It was meant to supplement other savings, not replace them.\n\nA 401(k) is an employer plan. Workers put part of their pay in, often before income tax, and some employers match. An employer match is part of your pay, so try to get the full match. A 403(b) is similar for some nonprofits and schools. An IRA is an account you open yourself. A traditional IRA may give a tax deduction now and is taxed later. A Roth IRA uses money already taxed, and qualified withdrawals are generally tax free. Limits and rules change, so check IRS.gov or a qualified adviser.\n\nEarly starters win because of compound growth.\n\nA will states how property is distributed. Keep beneficiaries up to date and plan for dependents.\n\nYour task is to name retirement sources, explain a match and compare IRAs. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Planning for Retirement and Providing for Family$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Insurance and Managing Risk$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Risk is the chance of loss. We cannot remove all risk, but we can plan for it. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished. Insurance is a way to share risk. You pay a regular amount called a premium, and the insurance company pays for covered losses.\n\nKnow the key terms. The premium is the price of the policy. The deductible is the amount you pay before the insurer pays. A copay is a fixed fee for a service, such as a doctor visit. Coinsurance is a percentage you share after the deductible. The out of pocket maximum is the most you pay in a year for covered health care. Coverage limits are the most the insurer will pay. Exclusions are things the policy does not cover.\n\nCommon types of insurance include these. Health insurance helps pay for medical care. Auto insurance covers damage and injury from accidents, and Florida law requires drivers to carry certain minimum coverage, so check current rules with the Florida Department of Highway Safety and Motor Vehicles. Renters insurance covers belongings and liability for tenants. Homeowners insurance covers a house and belongings, but standard policies generally do not cover flood damage, so homes in flood prone areas such as Florida's coast may need a separate flood policy, such as one through the National Flood Insurance Program. Wind and hurricane deductibles can be large, so read the policy. Life insurance provides money to dependents if the insured dies. Disability insurance replaces part of income if you cannot work.\n\nChoose insurance by comparing coverage and price from several companies and by raising the deductible only if you have savings to cover it. Insure what you cannot afford to lose, and do not pay for coverage you do not need. Keep a record of belongings with photos for claims. Pay premiums on time so coverage does not lapse.\n\nBe honest on applications. False information can lead to denied claims. Beware of insurance scams, and buy only from licensed agents.\n\nYour task: (1) Define premium, deductible and copay. (2) Name four types of insurance. (3) Explain why flood coverage matters in Florida.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished. Insurance is a way to prepare for the evil we can foresee.\n\nNow watch this. Insurance shares risk. You pay a premium. The deductible is what you pay before the insurer pays. A copay is a fixed fee for a service. Coinsurance is a percentage you share. The out of pocket maximum caps your yearly cost. Exclusions are what is not covered.\n\nHealth insurance helps pay for care. Auto insurance covers accidents, and Florida requires minimum coverage, so check current rules with the Florida Department of Highway Safety and Motor Vehicles. Renters insurance covers belongings. Homeowners insurance covers a house, but standard policies generally do not cover flood damage. In Florida you may need a separate flood policy, and hurricane deductibles can be large. Life insurance helps dependents. Disability insurance replaces part of income.\n\nCompare companies. Insure what you cannot afford to lose. Keep photos of belongings. Pay premiums on time. Be honest on applications and use licensed agents.\n\nYour task is to define insurance terms, name types and explain flood coverage. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Insurance and Managing Risk$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Major Purchases: Cars, Housing and Smart Shopping$j$, $j${"readings": [{"title": "Proverbs 21 (King James Version)", "url": "/portal/bible/Proverbs/21"}], "body": "Large purchases can build or break a budget. Luke 14:28 teaches us to count the cost, and Proverbs 21:20 says, There is treasure to be desired and oil in the dwelling of the wise; but a foolish man spendeth it up. Wise buyers plan, compare and wait.\n\nA car is often the first big purchase. The purchase price is only part of the cost. Add insurance, fuel, maintenance, registration, repairs and parking. Used cars cost less and lose value more slowly than new ones, but should be inspected by a trusted mechanic, and a vehicle history report can reveal accidents and title problems. When financing, get preapproved by a bank or credit union, compare the APR and the total cost, and limit the loan term. Leasing is a long term rental with mileage limits and fees, and you own nothing at the end. Read every page of a contract before signing.\n\nHousing is the largest expense for most people. Renting offers flexibility and fewer repair costs, but payments build no ownership. Buying can build equity, which is the value you own, but it brings a down payment, closing costs, taxes, insurance, repairs and risk of price changes. A common guideline is to keep housing costs to about one quarter to one third of take home pay, which varies by area. Read a lease carefully, know the deposit rules and document the condition of a rental when you move in.\n\nSmart shopping saves money for every purchase. Make a list and stick to it. Compare unit prices, which show cost per ounce or per item. Compare stores and read reviews from reliable sources. Use coupons and sales for items you were going to buy anyway. Wait twenty four hours before big impulse purchases. Understand the return and warranty policies. Be careful with extended warranties and store credit offers. Buying used, borrowing or repairing can also save money.\n\nAdvertising aims to create wants. Contentment, as taught in Hebrews 13:5, guards the heart against overspending.\n\nYour task: (1) List six costs of owning a car. (2) Compare renting and buying a home. (3) Describe five smart shopping habits.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. Listen, Proverbs 21:20 says, There is treasure to be desired and oil in the dwelling of the wise; but a foolish man spendeth it up. Wise buyers plan, compare and wait.\n\nNow watch this. A car costs more than the price. Add insurance, fuel, maintenance, registration, repairs and parking. Used cars cost less and lose value more slowly, but have a mechanic inspect them and check the vehicle history report. When financing, get preapproved, compare the APR and total cost and limit the term. Leasing is a long term rental and you own nothing at the end. Read every page of a contract.\n\nHousing is the biggest expense. Renting is flexible but builds no ownership. Buying can build equity but brings a down payment, closing costs, taxes, insurance and repairs. A common guideline is about one quarter to one third of take home pay. Read your lease and document the condition when you move in.\n\nShop smart. Make a list. Compare unit prices. Read reliable reviews. Wait twenty four hours before big impulse buys. Know return and warranty policies. Buying used, borrowing or repairing also saves money.\n\nHebrews 13:5 teaches contentment.\n\nYour task is to list car costs, compare renting and buying and describe shopping habits. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Major Purchases: Cars, Housing and Smart Shopping$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Investing, Retirement, Insurance and Major Purchases$j$, $j${"prompt": "Write a report of at least 250 words on planning for the future. Use complete sentences and label each part. Proverbs 22:3 says, A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.\n\nPart 1: Define stock, bond, mutual fund and index fund. Explain risk and return, diversification and why an offer of high returns with no risk is a warning sign.\nPart 2: Name three sources of retirement income. Explain an employer match, and compare a traditional IRA and a Roth IRA in general terms. Explain why starting early matters.\nPart 3: Define premium, deductible and copay. Name four types of insurance and explain why a Florida homeowner may need flood coverage.\nPart 4: List the costs of owning a car beyond the price. Compare renting and buying a home. Describe five smart shopping habits.\nPart 5: Explain how Ecclesiastes 11:2, 1 Timothy 5:8 and Luke 14:28 guide a believer who plans for the future.", "rubric": "100 points. Part 1: 25 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Investing, Retirement, Insurance and Major Purchases$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: A Prudent Man Foreseeth the Evil$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time when someone you know prepared for a hard event, such as a hurricane, with no names, (2) explains in your own words how insurance, savings and investing work together, (3) explains why a Christian should plan for family and the future, and (4) connects your answer to Proverbs 22:3, Ecclesiastes 11:2, 1 Timothy 5:8 or Proverbs 13:22. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a person plan ahead without being anxious? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: A Prudent Man Foreseeth the Evil$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Investing Basics: Risk, Return and Diversification$j$, $j${"questions": [{"q": "A share of ownership in a company is a:", "options": ["Bond", "Deposit", "Stock", "Premium"]}, {"q": "A loan to a company or government that pays interest is a:", "options": ["Bond", "Stock", "Deductible", "Dividend"]}, {"q": "Spreading money across many investments is called:", "options": ["Diversification", "Reconciliation", "Overdraft", "Withholding"]}, {"q": "An offer of very high returns with no risk is a sign of:", "options": ["Possible fraud", "A government program", "A savings account", "A safe deal"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Investing Basics: Risk, Return and Diversification$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,0}'::int[], array[$j$A stock represents ownership.$j$,$j$A bond is a loan.$j$,$j$Diversification reduces risk.$j$,$j$There is no guaranteed high return.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Investing Basics: Risk, Return and Diversification$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Planning for Retirement and Providing for Family$j$, $j${"questions": [{"q": "An employer sponsored retirement plan is a:", "options": ["401(k)", "Credit card", "Payday loan", "Checking account"]}, {"q": "Money an employer adds to your retirement plan is a:", "options": ["Match", "Fee", "Penalty", "Loan"]}, {"q": "Social Security is funded mainly by:", "options": ["Sales tax only", "Church offerings", "Payroll taxes", "Lotteries"]}, {"q": "Why does starting to invest early help?", "options": ["More years of compound growth", "It ends taxes", "It removes all risk", "It guarantees returns"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Planning for Retirement and Providing for Family$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,0}'::int[], array[$j$A 401(k) is offered through an employer.$j$,$j$A match is part of your compensation.$j$,$j$FICA payroll taxes fund it.$j$,$j$Time multiplies growth.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Planning for Retirement and Providing for Family$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Insurance and Managing Risk$j$, $j${"questions": [{"q": "The regular amount you pay for an insurance policy is the:", "options": ["Dividend", "Deductible", "Premium", "Principal"]}, {"q": "The amount you pay before insurance begins to pay is the:", "options": ["Premium", "Copay", "Limit", "Deductible"]}, {"q": "Standard homeowners policies generally do not cover:", "options": ["Fire damage", "Flood damage", "Theft", "Wind in every case"]}, {"q": "Insurance works by:", "options": ["Guaranteeing profits", "Sharing risk among many people", "Removing all risk", "Replacing savings"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Insurance and Managing Risk$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,1}'::int[], array[$j$The premium is the price of coverage.$j$,$j$A deductible comes first.$j$,$j$Flood usually needs separate coverage.$j$,$j$Many pay in so few can be covered.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Insurance and Managing Risk$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Major Purchases: Cars, Housing and Smart Shopping$j$, $j${"questions": [{"q": "The value of a home that you actually own is called:", "options": ["Equity", "Collateral only", "Principal only", "Premium"]}, {"q": "Which is part of the total cost of owning a car?", "options": ["Nothing after purchase", "Insurance and maintenance", "Nothing but gas", "Only the sticker price"]}, {"q": "A price per ounce or per item is called a:", "options": ["Unit price", "Interest rate", "Tax rate", "Premium"]}, {"q": "Before buying a used car, a wise buyer should:", "options": ["Ignore its history", "Buy on the first day", "Skip inspection", "Have a trusted mechanic inspect it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Major Purchases: Cars, Housing and Smart Shopping$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,3}'::int[], array[$j$Equity is the value you own.$j$,$j$Ownership has many ongoing costs.$j$,$j$Unit prices make comparison easy.$j$,$j$An inspection can reveal hidden problems.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Major Purchases: Cars, Housing and Smart Shopping$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Investing, Retirement, Insurance and Major Purchases$j$, $j${"questions": [{"q": "A loan to a company or government that pays interest is a:", "options": ["Copay", "Premium", "Stock", "Bond"]}, {"q": "Mixing many investments to reduce risk is:", "options": ["Inflation", "Diversification", "Reconciliation", "Withholding"]}, {"q": "In general, higher possible return comes with:", "options": ["Higher risk", "A government guarantee", "Lower fees always", "No risk"]}, {"q": "An employer match on a 401(k) is best described as:", "options": ["A penalty", "Extra money added to your retirement plan", "A loan", "A tax"]}, {"q": "A Roth IRA is funded with:", "options": ["Credit card advances", "Money that has already been taxed", "Borrowed funds", "Money never taxed ever"]}, {"q": "The amount you pay before insurance pays is the:", "options": ["APR", "Premium", "Dividend", "Deductible"]}, {"q": "Flood damage generally requires:", "options": ["A credit card", "No coverage", "A separate flood policy", "A bond"]}, {"q": "1 Timothy 5:8 teaches believers to:", "options": ["Borrow instead of working", "Hide money", "Ignore family needs", "Provide for their own household"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Investing, Retirement, Insurance and Major Purchases$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,1,1,3,2,3}'::int[], array[$j$A bond is a loan.$j$,$j$Do not put all eggs in one basket.$j$,$j$Risk and return are linked.$j$,$j$It is part of your compensation.$j$,$j$Qualified withdrawals are generally tax free.$j$,$j$That is the deductible.$j$,$j$Standard homeowners policies exclude flood.$j$,$j$Providing for family is part of faithfulness.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Investing, Retirement, Insurance and Major Purchases$j$ on conflict (item_id) do nothing;
